<h1>Notifications</h1><p>Trade journal reminders and workflow alerts.</p><div class="card table-wrap"><table><thead><tr><th>Date</th><th>Type</th><th>Title</th><th>Message</th><th></th></tr></thead><tbody><?php foreach($notifications as $n):?><tr><td><?=e($n['created_at'])?></td><td><?=e($n['type'])?></td><td><strong><?=e($n['title'])?></strong></td><td><?=e($n['message'])?></td><td><?php if(!$n['is_read']):?><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=e($n['id'])?>"><button class="secondary">Mark read</button></form><?php else:?>Read<?php endif;?></td></tr><?php endforeach;if(!$notifications):?><tr><td colspan="5" class="muted">No notifications.</td></tr><?php endif;?></tbody></table></div>
